package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Rollup;

/** A transfer that went through: the sheet left, the sheet arrived on, the person's name, and the other sheet's
 *  figures before the person arrived. */
public record Transfer(String fromSheet, String toSheet, String name, Rollup toBefore) {
}
package net.officefloor.hq.app.person;

/** A validated transfer: the signed-in user, and the id of the sheet transferred to (trimmed). */
public record TransferInput(String user, String toSheet) {
}
package net.officefloor.hq.app.person;

/** Body of transferring a person to another sheet: who is doing it, and the id of the other sheet. */
public record TransferRequest(String user, String toSheet) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.plugin.variable.Val;

/** Record the transfer in the audit file: on this sheet, then how its figures moved; on the other sheet, then how
 *  its figures moved. */
public class AuditPersonTransferred {
    public void audit(@Val TransferInput input, @Val Transfer transfer, @Val Rollup before, Audit audit,
            Rollups rollups) {
        audit.record("PERSON_TRANSFERRED sheet=" + transfer.fromSheet() + " by=" + input.user() + " name="
                + transfer.name() + " to=" + transfer.toSheet());
        rollups.record(transfer.fromSheet(), input.user(), before);
        audit.record("PERSON_TRANSFERRED sheet=" + transfer.toSheet() + " by=" + input.user() + " name="
                + transfer.name() + " from=" + transfer.fromSheet());
        rollups.record(transfer.toSheet(), input.user(), transfer.toBefore());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.patron.PatronRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Transfer the loaded person to another sheet: only a steward may, a person not retired, to a sheet other than this
 *  one (created when never loaded) that is not archived and has none of their name, aliases or contact. They arrive
 *  with every grade they were given (and its from-date), their terms, contact and aliases, and their claims (status,
 *  dates, notes, settled dues and logs kept; each claim that had a number takes the next number of the other sheet,
 *  in the order the claims were added; unbound from any statement; references dropped), with no statement taken.
 *  They leave this sheet entirely: their patron links, pool memberships, holds, statements and watchers are dropped. */
public class TransferPerson {
    public void transfer(@Val TransferInput input, @Val Person loaded, PersonRepository people, ClaimRepository claims,
            PatronRepository patrons, PoolRepository pools, WatchRepository watches, RoleRepository roles,
            SheetRepository sheets, Rollups rollups, Out<Transfer> transfer, Out<PersonResponse> saved)
            throws InvalidPersonException {
        String from = loaded.sheetId();
        String to = input.toSheet();
        if (!Role.STEWARD.equals(roles.of(from, input.user()))) {
            throw new InvalidPersonException("Only a steward may transfer people.");
        }
        if (to.equals(from)) {
            throw new InvalidPersonException(loaded.name() + " is already on this sheet.");
        }
        people.lock(loaded);
        Person person = people.find(from, loaded.id());
        if (person == null) {
            throw new InvalidPersonException("That person is no longer on this sheet.");
        }
        if (person.retiredFrom() != null) {
            throw new InvalidPersonException(person.name() + " is retired and cannot be transferred.");
        }
        sheets.ensure(to, input.user());
        if (sheets.archived(to)) {
            throw new InvalidPersonException("Sheet " + to + " is archived: nobody can be transferred to it.");
        }
        if (people.nameInUse(to, person.name(), null)) {
            throw new InvalidPersonException("Sheet " + to + " already has the name " + person.name() + ".");
        }
        for (String alias : person.aliases()) {
            if (people.nameInUse(to, alias, null)) {
                throw new InvalidPersonException("Sheet " + to + " already has the name " + alias + ".");
            }
        }
        if (person.contact() != null && people.contactInUse(to, person.contact(), null)) {
            throw new InvalidPersonException("Sheet " + to + " already has someone with the contact "
                    + person.contact() + ".");
        }
        var toBefore = rollups.take(to);
        patrons.drop(from, person.id());
        pools.drop(from, person.id());
        watches.drop(from, person.id());
        claims.transfer(from, person.id(), to);
        people.transfer(person, to);
        transfer.set(new Transfer(from, to, person.name(), toBefore));
        saved.set(PersonResponse.from(people.find(to, person.id())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user and a sheet to transfer to. */
public class ValidateTransfer {
    public void validate(@RequestBody TransferRequest request, Out<TransferInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before transferring people.");
        }
        if (request.toSheet() == null || request.toSheet().isBlank()) {
            throw new InvalidPersonException("Enter the id of the sheet to transfer to.");
        }
        body.set(new TransferInput(request.user().trim(), request.toSheet().trim()));
    }
}
package net.officefloor.hq.app.person;

/** A merge that went through: the sheet, the merged person's name and the name of the person merged into. */
public record Merge(String sheetId, String from, String into) {
}
package net.officefloor.hq.app.person;

/** A validated merge: the signed-in user, and the id of the person merged into. */
public record MergeInput(String user, long intoId) {
}
package net.officefloor.hq.app.person;

/** Body of merging a person into another: who is doing it, and the id of the person merged into. */
public record MergeRequest(String user, Long intoId) {
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a signed-in user and a person to merge into. */
public class ValidateMerge {
    public void validate(@RequestBody MergeRequest request, Out<MergeInput> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before merging people.");
        }
        if (request.intoId() == null) {
            throw new InvalidPersonException("Choose a person to merge into.");
        }
        body.set(new MergeInput(request.user().trim(), request.intoId()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.patron.PatronRepository;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Merge the loaded person into another: only a steward may, into another person on the sheet, neither of them
 *  retired. The merged person's claims move to the other (numbers and dates kept, listed after the other's in the
 *  order they were added, each unbound from any statement); their name and aliases become aliases of the other;
 *  their patrons are added to the other's (not the other themselves, no repeats), and anyone naming them as patron
 *  names the other instead (no repeats); their pool memberships move to the other (shares added when the other is
 *  already a member); their statements, holds, watchers and contact are dropped, and they leave the sheet. */
public class MergePerson {
    public void merge(@Val MergeInput input, @Val Person loaded, PersonRepository people, ClaimRepository claims,
            PatronRepository patrons, PoolRepository pools, WatchRepository watches, RoleRepository roles,
            Out<Merge> merge, Out<PersonResponse> saved) throws InvalidPersonException {
        if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
            throw new InvalidPersonException("Only a steward may merge people.");
        }
        Person into = people.find(loaded.sheetId(), input.intoId());
        if (into == null) {
            throw new InvalidPersonException("No person " + input.intoId() + " on this sheet.");
        }
        if (into.id() == loaded.id()) {
            throw new InvalidPersonException(loaded.name() + " cannot be merged into themselves.");
        }
        people.lock(loaded);
        people.lock(into);
        Person from = people.find(loaded.sheetId(), loaded.id());
        into = people.find(into.sheetId(), into.id());
        if (from == null || into == null) {
            throw new InvalidPersonException("That person is no longer on this sheet.");
        }
        if (from.retiredFrom() != null) {
            throw new InvalidPersonException(from.name() + " is retired and cannot be merged.");
        }
        if (into.retiredFrom() != null) {
            throw new InvalidPersonException(into.name() + " is retired: nobody can be merged into them.");
        }
        claims.moveAll(from.sheetId(), from.id(), into.id());
        patrons.merge(from.sheetId(), from.id(), into.id());
        pools.merge(from.sheetId(), from.id(), into.id());
        watches.drop(from.sheetId(), from.id());
        people.merge(from, into);
        merge.set(new Merge(from.sheetId(), from.name(), into.name()));
        saved.set(PersonResponse.from(people.find(into.sheetId(), into.id())));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the merge in the audit file. */
public class AuditPersonMerged {
    public void audit(@Val MergeInput input, @Val Merge merge, Audit audit) {
        audit.record("PERSON_MERGED sheet=" + merge.sheetId() + " by=" + input.user() + " from=" + merge.from()
                + " into=" + merge.into());
    }
}
